SELECT t1.id, t1.ledger_id, t1.month, t1.category_id, t2.name AS category_name, t1.amount FROM jz_budgets t1 LEFT JOIN jz_categories t2 ON t2.id = t1.category_id AND t2.is_deleted = 0 WHERE t1.is_deleted = 0
AND t1.user_id = #{queryParams.userId}
AND t1.ledger_id = #{queryParams.ledgerId}
AND t1.month BETWEEN
${m}
AND t1.category_id = #{queryParams.categoryId}
ORDER BY t1.month DESC, t1.id ASC
